INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch11$PT156-S2-Q25$batch11$, 156, 2, 25, $batch11$Sufficient Assumption$batch11$, $batch11$According to the Newtonian theory of gravity, the gravitational force between two bodies depends exclusively on their mass and the distance between them, but is independent of what the bodies are made of. Thus, according to the Newtonian theory, one does not need a theory of the structure and constitution of the Sun and the planets in order to calculate their orbits.$batch11$, $batch11$The conclusion of the argument above follows logically if which one of the following is assumed?$batch11$, $batch11$B$batch11$, true, $batch11$Batch 11; question text from local bank.$batch11$ FROM lr_sections s WHERE s.preptest=156 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q25$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$A$batch11$, $batch11$Mass is dependent on gravitational force.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q25$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$A$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$B$batch11$, $batch11$According to the Newtonian theory, the calculation of planetary orbits requires considering only their gravitational forces.$batch11$, $batch11$Correct$batch11$, true FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q25$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$B$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$C$batch11$, $batch11$The Newtonian theory of gravity is mistaken about the data needed to calculate gravitational force.$batch11$, $batch11$Opposite$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q25$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$C$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$D$batch11$, $batch11$Knowing what an object is made of is sufficient for determining its mass.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q25$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$D$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$E$batch11$, $batch11$The gravitational force between the Sun and a planet is a factor in determining the distance between them.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q25$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$E$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q25$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Conclusion$batch11$, $batch11$Under Newtonian theory, you don't need a theory of what the Sun and planets are made of to calculate their orbits.$batch11$), (1, $batch11$Evidence$batch11$, $batch11$Under Newtonian theory, gravitational force depends only on mass and distance, not on what bodies are made of.$batch11$), (2, $batch11$Evaluate$batch11$, $batch11$The evidence is about gravitational force. The conclusion is about orbits. Bridge them: if calculating orbits requires only gravitational force, and gravitational force doesn't depend on composition, then orbits don't need composition either.$batch11$), (3, $batch11$Goal$batch11$, $batch11$Under Newtonian theory, calculating orbits requires only gravitational forces.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT156-S2-Q25$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$This reverses the relationship and still says nothing about orbits.$batch11$), ($batch11$B$batch11$, $batch11$Orbits need only gravitational force, and gravitational force ignores composition. So orbits don't need composition.$batch11$), ($batch11$C$batch11$, $batch11$If the theory is mistaken, it undercuts the argument rather than completing it.$batch11$), ($batch11$D$batch11$, $batch11$Composition being enough to find mass doesn't show it's unnecessary for orbits.$batch11$), ($batch11$E$batch11$, $batch11$This links force to distance but doesn't say orbits depend only on force.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT156-S2-Q25$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
